import { livePage, initLive, mountLiveMap } from './journey-ui.mjs';
import { HOME, PLACES, TYPES, DEFAULT, time, planDay, conflicts, validatePlan, calendarEvents, makeICS } from './planner.mjs';
const $=s=>document.querySelector(s);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6l1.4 1.4m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',home:'m3 10 9-7 9 7v10H3Zm6 10v-7h6v7',route:'M5 5a2 2 0 1 0 0 .1M19 19a2 2 0 1 0 0 .1M7 5h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h8',calendar:'M4 5h16v16H4ZM8 3v4m8-4v4M4 10h16m-11 4h1m4 0h1m-6 4h1m4 0h1',news:'M5 3h14v18H5ZM8 7h8M8 11h8m-8 4h3m2 0h3m-8 3h8',memory:'M9 3 6 5v3l-3 2v4l3 2v3l3 2 3-2 3 2 3-2v-3l3-2v-4l-3-2V5l-3-2-3 2Zm3 2v14M6 8l3 2m9-2-3 2M6 16l3-2m9 2-3-2',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',leaf:'M20 3C8 2 2 9 6 16s14 1 14-13ZM5 21 16 8',bolt:'m13 2-9 12h7l-1 8L20 9h-7Z',wallet:'M3 6h17v14H3ZM3 6V3h14v3m0 6h4v5h-4Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',lock:'M6 10h12v11H6Zm3 0V6a3 3 0 0 1 6 0v4',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',bell:'M6 16V9a6 6 0 0 1 12 0v7l2 2H4Zm4 5h4',hair:'m8 9 12 11M8 15 20 3M9 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM9 17a3 3 0 1 1-6 0 3 3 0 0 1 6 0',ramen:'M3 11h18a9 9 0 0 1-18 0ZM7 21h10M7 3v4m5-5v5m5-4v4M3 8l18-5',movie:'M3 8h18v13H3ZM3 3h18v5H3Zm3 0 3 5m4-5 3 5',train:'M6 3h12v15H6ZM6 10h12m-9 5h1m4 0h1M8 18l-2 3m10-3 2 3',walk:'M14 4a1 1 0 1 1-2 0 1 1 0 0 1 2 0ZM8 10l4-3 3 5 4 1M12 7l-2 8-4 6m4-6 5 3 1 4',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',undo:'M8 3 3 8l5 5M3 8h10a7 7 0 1 1 0 14',shield:'m12 2 8 3v7c0 6-8 10-8 10S4 18 4 12V5Zm-4 9 3 3 5-6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',coffee:'M4 8h12v8a5 5 0 0 1-10 0V8m10 1h3a3 3 0 0 1 0 6h-3M8 2v3m5-3v3M3 22h16',edit:'m4 16 12-12 4 4L8 20H4Zm10-10 4 4',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 11v6m0-10v1',external:'M14 3h7v7m0-7L10 14M9 3H3v18h18v-6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.spark}"/></svg>`;
const KEY='daylight-demo-en-v1';
const seed=()=>({version:1,date:'2026-10-04',constraints:{...DEFAULT},approved:null,locks:[],meetings:[],reminders:[{id:'water',title:'Time for a glass of water',detail:'Move around to regain focus',done:false}],memories:[{id:'transit',label:'Prioritize public transport',detail:'Used to choose travel mode',kind:'transport',value:'transit'},{id:'budget',label:'Afternoon travel budget ¥200',detail:'Used for default budget constraint',kind:'budget',value:200},{id:'interest',label:'Follow AI and semiconductors',detail:'Example topic of interest · Currently only personal notes',kind:'interest',value:'AI and semiconductors'}],audit:[],briefRead:false,dnd:false});
let state;try{const saved=JSON.parse(localStorage.getItem(KEY));state=saved?.version===1?saved:seed();}catch{state=seed();}
const viewFromHash=()=>['live','today','planner','calendar','brief','memory'].includes(location.hash.slice(1))?location.hash.slice(1):'live';
let view=viewFromHash(),selected='relaxed',selectedStop=null,result,intentText='',assistant='What you want to do, leave it to me to arrange together. Today’s plan will reference your travel preferences and leave buffer for each leg.',busy=false,status={mode:'demo'},draft=null,reminderTimer;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser cannot save data; closing the page may cause loss.');}}
function audit(text){state.audit.unshift({text,at:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});state.audit=state.audit.slice(0,30);}
function calculate(){result=planDay(state.constraints,state.meetings,state.locks);if(!result.plans.some(p=>p.id===selected))selected=result.plans[0]?.id||'relaxed';}
calculate();
const current=()=>result.plans.find(p=>p.id===selected);
const navs=[['live','pin','Assistant conversation'],['today','home','Demo overview'],['planner','route','Shanghai demo'],['calendar','calendar','Demo calendar'],['brief','news','Daily brief'],['memory','memory','Preferences and memory']];
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function modal(content){$('#modal').innerHTML=`<button class="icon-button modal-close" data-action="close" aria-label="Close popup">${icon('close')}</button>${content}`;$('#modal').showModal();}
function close(){$('#modal').close();}
function subtitle(kicker,title,extra=''){return `<div class="section-title"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2></div>${extra}</div>`;}
function header(){const titles={live:['YOUR PERSONAL ASSISTANT','Start today with a sentence','Discuss ideas, plan outings, and discover local news and events.'],today:['YOUR DAY, A LITTLE LIGHTER','Good morning, Zhuoer','Today, leave time for things you like.'],planner:['LESS PLANNING. MORE LIVING.','What you want to do, all well arranged.','Tell me your thoughts so we can find a comfortable rhythm together.'],calendar:['A LITTLE ROOM FOR LIFE','The pace of your day, decided by you.','Confirmed arrangements and locked commitments, crystal clear.'],brief:['A QUIETER WAY TO STAY INFORMED','Only read what matters to you.','Give information a little order, give yourself some space.'],memory:['PERSONAL, ON YOUR TERMS','The better I know you, the more it suits you.','Remember useful preferences and always allow changing your mind.']};const t=titles[view];return `<header class="topbar"><div class="breadcrumb">My Space <span>/</span> ${navs.find(n=>n[0]===view)[2]}</div><div class="top-right"><span class="demo-badge"><i></i>${status.mode==='live'?'Nemotron Configured':'Interactive Demo'}</span><button class="icon-button" data-action="notifications" aria-label="View notifications">${icon('bell')}<b class="notification-dot"></b></button><span class="avatar">Z</span></div></header><div class="greeting"><div><span class="eyebrow">${t[0]}</span><h1>${t[1]}${view==='today'?` <span class="greeting-sun">${icon('sun')}</span>`:''}</h1><p>${t[2]}</p></div><div class="date-chip">${icon('calendar')}<div>${view==='live'?'Stockholm · SEK<small>Europe/Stockholm</small>':'Sunday, 4 October<small>Demo Day · Shanghai Time Zone</small>'}</div></div></div>`;}
function illustration(){return `<svg class="hero-art" viewBox="0 0 370 245" aria-hidden="true"><defs><clipPath id="arch"><path d="M65 245V114a114 114 0 0 1 228 0v131Z"/></clipPath><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#d7e8be"/><stop offset="1" stop-color="#e7edd1"/></linearGradient></defs><g clip-path="url(#arch)"><path fill="url(#sky)" d="M40 0h280v245H40z"/><circle cx="244" cy="61" r="28" fill="#f2c779"/><path d="M45 200 340 115v150H45" fill="#8eab8c"/><path d="M43 247 235 153l86 90" fill="#b6c59a"/><path d="m-10 243 365-44" stroke="#eee6cb" stroke-width="24"/><path d="m202 245 110-95" stroke="#eee6cb" stroke-width="12"/><rect x="100" y="104" width="73" height="93" rx="3" fill="#eee5d0"/><path d="m95 104 42-34 41 34" fill="#c27e5d"/><rect x="116" y="128" width="17" height="26" rx="8" fill="#536c55"/><rect x="144" y="128" width="17" height="26" rx="8" fill="#536c55"/><path d="M125 197v-23a11 11 0 0 1 22 0v23" fill="#bc916b"/><rect x="214" y="120" width="70" height="69" rx="2" fill="#d5ab7a"/><rect x="209" y="114" width="81" height="10" fill="#7e8a5d"/><rect x="225" y="140" width="17" height="23" fill="#eee5d0"/><rect x="253" y="140" width="17" height="23" fill="#eee5d0"/><path d="M78 142v70m105-86v68m118-103v83" stroke="#647051" stroke-width="4"/><ellipse cx="78" cy="143" rx="22" ry="35" fill="#688a62"/><ellipse cx="183" cy="125" rx="16" ry="30" fill="#79935f"/><ellipse cx="301" cy="104" rx="23" ry="44" fill="#54775b"/><path d="m63 224 195-30" stroke="#b29d70" stroke-width="2" stroke-dasharray="5 8"/></g><path d="M65 245V114a114 114 0 0 1 228 0v131" fill="none" stroke="#d6e5b4" stroke-opacity=".3"/><g transform="translate(274 29) rotate(12)"><rect width="68" height="64" rx="12" fill="#f5f2e4"/><path d="m18 31 12 10 23-22" fill="none" stroke="#42644e" stroke-width="4" stroke-linecap="round"/></g><g transform="translate(30 159) rotate(-10)"><rect width="67" height="59" rx="12" fill="#e6bd83"/><path d="M19 33c0-16 17-12 14-1-3-11 14-15 14-3 0 8-14 17-14 17S19 39 19 33" transform="translate(0 -8)" fill="#785638"/></g><path d="m316 133 3 9 9 3-9 3-3 9-3-9-9-3 9-3Z" fill="#d3dda9"/></svg>`;}
function hero(){return `<section class="hero"><div class="hero-copy"><span class="hero-kicker"><span></span> YOUR PERSONAL DAY COMPANION</span><h2>Days do not need to be packed,<br>Just right enough.</h2><p>A bowl of hot soup, a movie, a new hairstyle.<br>You look forward, I will take care of the plans.</p><button class="button light" data-action="focus-plan">Plan my afternoon ${icon('arrow')}</button></div>${illustration()}<span class="hero-caption">A little intention. A lovely day.</span></section>`;}
function quickCards(){return `<div class="quick-cards"><button data-action="nav" data-view="brief" class="quick-card"><span class="round-icon peach">${icon('news')}</span><span><strong>Your morning briefing</strong><small>${state.briefRead?'Read · Come back anytime to check':'3 Focus areas · 2 Minute read'}</small></span>${icon('chevron')}</button><button data-action="nav" data-view="calendar" class="quick-card"><span class="round-icon sage">${icon('calendar')}</span><span><strong>${state.approved?`${state.approved.stops.length + state.meetings.length} Confirmed items`:'Afternoon, save for yourself'}</strong><small>${state.approved?'Calendar and reminders saved locally':'Now is a good time to plan a little joy'}</small></span>${icon('chevron')}</button><button data-action="reminder" class="quick-card"><span class="round-icon lavender">${icon('coffee')}</span><span><strong>Do not forget to take care of yourself too</strong><small>${state.dnd?'Do Not Disturb enabled · Activity alerts paused':'Drink a glass of water, get up and walk a bit'}</small></span>${icon('chevron')}</button></div>`;}
function composer(){return `<section class="composer card" id="composer">${subtitle('MAKE A LITTLE PLAN','How would you like to spend this afternoon?',`<span class="subtle-tag">${icon('spark')} ${status.mode==='live'?'Nemotron Intent Parsing':'Local Scenario Demo'}</span>`)}<form id="intent-form"><div class="prompt-input"><textarea id="intent" name="intent" aria-label="Tell Daylight Your itinerary needs" placeholder="For example: want a haircut, eat ramen, watch a movie, budget 200 yuan, evening 8 before heading home…" rows="2" maxlength="2000">${escape(intentText)}</textarea><button class="send-button" type="submit" aria-label="Generate itinerary" ${busy?'disabled':''}>${busy?'<span class="spinner"></span>':icon('arrow')}</button></div></form><div class="prompt-bottom"><span>${icon('shield')} ${status.mode==='live'?'When submitting, send this request and constraints to Nebius':'Example location · No need to connect personal account'}</span><button class="text-button" data-action="sample">Try haircut + Ramen + Film ${icon('plus')}</button></div><details class="constraints"><summary>${icon('settings')} Adjust budget and time <span>¥${state.constraints.budget} · ${time(state.constraints.start)} Depart · ${time(state.constraints.deadline)} Return home</span>${icon('chevron')}</summary><form id="constraints-form"><div class="form-grid"><label>Budget limit<input name="budget" type="number" min="0" max="10000" required value="${state.constraints.budget}"></label><label>Departure time<input name="start" type="time" min="06:00" required value="${time(state.constraints.start)}"></label><label>Latest return home<input name="deadline" type="time" required value="${time(state.constraints.deadline)}"></label><label>Travel mode<select name="transport"><option value="transit" ${state.constraints.transport==='transit'?'selected':''}>Public transit priority</option><option value="walk" ${state.constraints.transport==='walk'?'selected':''}>Walking all the way</option></select></label></div><div class="form-footer"><div class="checks">${Object.entries(TYPES).map(([id,label])=>`<label><input type="checkbox" name="activities" value="${id}" ${state.constraints.activities.includes(id)?'checked':''}>${label}</label>`).join('')}</div><button class="button small" type="submit">Update plan ${icon('arrow')}</button></div></form></details></section>`;}
function planOptions(){return `<div class="plan-options" role="group" aria-label="Select itinerary options">${result.plans.map(p=>`<button class="plan-option ${p.id===selected?'selected':''}" data-action="select-plan" data-id="${p.id}" aria-pressed="${p.id===selected}"><div class="option-title">${icon(p.icon)}<strong>${p.name}</strong>${p.id===selected?`<span class="check-dot">${icon('check')}</span>`:''}</div><p>${p.description}</p><div class="option-stats"><b>¥${p.cost}</b><span>Walking ${p.walking}  minutes</span></div></button>`).join('')}</div>`;}
function routeMap(p){if(!p)return '';const colors=['#466957','#ce8f57','#7473a0'];const points=[HOME,...p.stops,HOME];return `<div class="route-map"><svg viewBox="0 0 480 355" role="img" aria-label="Route illustration in fictional area"><defs><pattern id="blocks" width="88" height="65" patternUnits="userSpaceOnUse" patternTransform="rotate(-12)"><rect width="88" height="65" fill="#eeede4"/><rect x="6" y="6" width="70" height="46" rx="5" fill="#e1e2d6" stroke="#dbded1"/></pattern><filter id="pin-shadow"><feDropShadow dx="0" dy="3" stdDeviation="3" flood-opacity=".12"/></filter></defs><rect width="480" height="355" fill="url(#blocks)"/><path d="M400-30C255 34 513 182 357 246S363 380 312 390" fill="none" stroke="#ccdedd" stroke-width="35"/><path d="M-20 100 505 197M110-15 207 375M-10 279 520 118" stroke="#faf9f3" stroke-width="13"/><path d="m-20 100 525 97M110-15l97 390M-10 279l530-161" stroke="#d9d8ca" stroke-width="1" stroke-dasharray="2 3"/><path d="m18 26 72-15 21 58-73 16Z" fill="#cfdac1"/><path d="m201 256 55-4 18 59-51 17Z" fill="#d1ddc3"/><g fill="#9a9d8c" font-size="10" font-family="sans-serif"><text x="28" y="54">Wutong Garden</text><text x="214" y="295">Greenland Park</text><text x="78" y="197" transform="rotate(-17 78 197)">Phoenix tree Paulownia Road</text><text x="264" y="47">River Bank Street District</text><text x="270" y="331">New Inner Street District</text></g><polyline points="${points.map(v=>`${v.x},${v.y}`).join(' ')}" fill="none" stroke="#fff" stroke-width="7" stroke-linejoin="round"/><polyline points="${points.map(v=>`${v.x},${v.y}`).join(' ')}" fill="none" stroke="#567b63" stroke-width="3" stroke-linejoin="round" stroke-dasharray="6 5"/><g transform="translate(${HOME.x} ${HOME.y})"><circle r="15" fill="#fff" stroke="#54705b" stroke-width="2"/><path d="m-7 0 7-6 7 6v7H-7Z" fill="#54705b"/></g><text x="${HOME.x-7}" y="${HOME.y+32}" fill="#526153" font-size="11">Home</text>${p.stops.map((s,i)=>`<g class="map-marker ${selectedStop===s.id?'focused':''}" data-action="stop" data-id="${s.id}" transform="translate(${s.x} ${s.y})" role="button" tabindex="0" aria-label="View${escape(s.name)}"><circle r="18" fill="${colors[i]}" stroke="#fff" stroke-width="3" filter="url(#pin-shadow)"/><text y="5" text-anchor="middle" fill="#fff" font-size="13" font-weight="700">${i+1}</text><rect x="-55" y="-48" width="110" height="23" rx="6" fill="#fff" opacity=".96"/><text y="-33" text-anchor="middle" fill="#465346" font-size="10">${s.name}</text></g>`).join('')}</svg><div class="map-top"><span>${icon('pin')} Shanghai · Fictional district</span><span class="map-compass">N ↑</span></div><div class="map-legend"><span><i></i> ${p.stops.length} Several destinations, a convenient arrangement</span><small>Illustration · Not suitable for actual navigation</small></div></div>`;}
function itinerary(p){return `<div class="itinerary"><div class="itinerary-start"><span>${time(state.constraints.start)}</span><b></b><span>Depart from home ${icon(state.constraints.transport==='walk'?'walk':'train')}</span></div>${p.stops.map((s,i)=>`${s.wait>15?`<div class="wait-row">${icon('clock')} ${time(s.arrival)}–${time(s.start)} · Wait / Online meeting available</div>`:''}<button class="stop-row ${selectedStop===s.id?'active':''}" data-action="stop" data-id="${s.id}"><div class="stop-time">${time(s.start)}<small>${time(s.end)}</small></div><span class="stop-icon stop-${s.type}">${icon(s.type)}</span><div class="stop-copy"><strong>${s.name}</strong><span>${s.type==='movie'?'Finding the Light · Fictional film':s.note.split(' · ')[0]}</span><small>★ ${s.rating} <em>Sample rating</em> · ¥${s.price}${state.locks.some(l=>l.id===s.id)?` <b class="locked">${icon('lock')}Locked</b>`:''}</small></div></button>${i<p.stops.length-1?`<div class="travel-row">${icon(p.legs[i+1].mode==='Walking'?'walk':'train')} ${p.legs[i+1].mode}approximately ${p.legs[i+1].minutes}  minutes <span>· Also keep 5 Minutes to shop buffer</span></div>`:''}`).join('')}<div class="itinerary-end"><span>${time(p.homeAt)}</span><b>${icon('home')}</b><span>Return home <small>Earlier than latest home return ${p.buffer}  minutes</small></span></div></div>`;}
function planSection(){const p=current();return `<section class="plan-section card" id="plan-section">${subtitle('A PLAN THAT FITS YOU',state.approved?'Allow changes, leave some margin':'Find three good options for you',`<button class="text-button" data-action="trace">${icon('shield')} Check verification</button>`)}${p?`${planOptions()}<div class="plan-detail"><div class="timeline-panel"><div class="micro-heading">Your afternoon <span>${p.stops.length} Things you want to do</span></div>${itinerary(p)}</div><div class="map-panel">${routeMap(p)}<div class="map-note">${icon('leaf')}<span>${p.walking<=25?'Slow your pace, and you can still finish the things you love':'Walk and pause, let the city become part of today'}</span></div></div></div><div class="plan-footer"><div><strong>Estimated ¥${p.cost}</strong><span>Includes transport · Budget remaining ¥${state.constraints.budget-p.cost}</span></div><button class="button" data-action="confirm-plan" ${busy?'disabled':' '}>${state.approved?'Preview and update calendar':'Just go with this plan'} ${icon('arrow')}</button></div>`:`<div class="empty-state">${icon('route')}<h3>Leave a little room first, then set out</h3><p>${escape(result.reason)}</p><button class="button" data-action="edit-constraints">Adjust constraints</button></div>`}<div class="data-note">${icon('info')} Locations, ratings, sessions, and transport are examples; hair appointment still awaiting merchant confirmation</div></section>`;}
function assistantCard(){return `<section class="assistant-card"><div class="assistant-heading"><span class="brand-mark mini">✳</span><strong>Daylight Little thoughts</strong><span class="online-dot"></span></div><p>${escape(assistant)}</p><div class="memory-hint">${icon('memory')} Reference preference:${state.constraints.transport==='transit'?'Public transit priority':'Walking all the way'}</div><div class="assistant-divider"></div><span class="eyebrow">WHEN PLANS CHANGE</span><h3>Plan changed? It’s fine.</h3><p class="small-copy">Try adding an ad-hoc meeting, see how I keep your confirmed arrangements.</p><button class="button outline full" data-action="add-meeting">${icon('plus')} Simulate new meeting</button></section>`;}
function remindersCard(){return `<section class="card reminders-card">${subtitle('LITTLE THINGS','Remember, it can also be easy',`<button class="icon-button" data-action="new-reminder" aria-label="Add reminder">${icon('plus')}</button>`)}<div class="reminders-list">${state.reminders.slice(0,5).map(r=>`<div class="reminder-row ${r.done?'done':''}"><button class="check-button" data-action="toggle-reminder" data-id="${escape(r.id)}" aria-label="${r.done?'Cancel completion':'Complete'}${escape(r.title)}" aria-pressed="${r.done}">${r.done?icon('check'):''}</button><div><strong>${escape(r.title)}</strong><small>${escape(r.detail)}</small></div></div>`).join('')}</div><button class="text-button reminder-test" data-action="reminder">${icon('bell')} Try activity reminder</button></section>`;}
function briefMini(){return `<section class="brief-mini"><span class="eyebrow">A MOMENT TO CATCH UP</span><div class="brief-mini-title"><h3>The world is big,<br>First look at what you care about.</h3><div class="paper-icon">${icon('news')}</div></div><p>AI Infrastructure · Semiconductor · Tech trends</p><button class="text-button" data-action="nav" data-view="brief">Open my briefing ${icon('arrow')}</button><span class="tiny-note">Content structure demonstration · Non-realtime financial news</span></section>`;}
function homePage(){return `${hero()}${quickCards()}<div class="workspace-grid"><div class="main-column">${composer()}${planSection()}</div><aside class="right-column">${assistantCard()}${remindersCard()}${briefMini()}</aside></div>`;}
function plannerPage(){return `<div class="workspace-grid"><div class="main-column">${composer()}${planSection()}</div><aside class="right-column">${assistantCard()}<section class="card guide-card"><span class="eyebrow">YOU'RE IN CONTROL</span><h3>You decide, the assistant coordinates.</h3><p>${icon('check')} Check first, then recommend</p><p>${icon('lock')} Keep locked movies</p><p>${icon('calendar')} Update local calendar only after confirmation</p><p>${icon('shield')} Will not pay or contact merchants</p></section></aside></div>`;}
function allEvents(){return [...(state.approved?calendarEvents(state.approved,state.date):[]),...state.meetings.map(m=>({...m,date:state.date,location:'Online meeting · Demo',source:'meeting'}))].sort((a,b)=>a.start-b.start);}
function calendarPage(){const events=allEvents(),broken=state.approved?conflicts(state.approved,state.meetings):[];return `<div class="calendar-layout"><section class="card calendar-card">${subtitle('SUNDAY, OCTOBER 04','Today’s schedule',`<div class="inline-actions"><button class="button outline small" data-action="export" ${!events.length?'disabled':''}>${icon('download')} Export calendar</button><button class="button small" data-action="add-meeting">${icon('plus')} Add meeting</button></div>`)}<div class="week-strip">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map((d,i)=>`<div class="${i===6?'today':''}"><span>${d}</span><strong>${[28,29,30,1,2,3,4][i]}</strong><b></b></div>`).join('')}</div>${broken.length?`<div class="conflict-banner">${icon('info')} New meeting conflicts with original schedule. Original plan has not been changed.<button data-action="repair" class="text-button">View repair solution ${icon('arrow')}</button></div>`:''}<div class="calendar-events">${events.length?events.map(e=>`<div class="calendar-event ${e.source==='meeting'?'meeting-event':''}"><div class="event-time">${time(e.start)}<small>${time(e.end)}</small></div><div class="event-body"><span class="event-type">${e.source==='meeting'?'Meeting · Local demonstration':'Personal itinerary'}</span><h3>${escape(e.title)}</h3><p>${icon('pin')} ${escape(e.location)}</p></div>${state.locks.some(l=>l.id===e.venueId)?`<button class="tag lock-tag" data-action="unlock" data-id="${e.venueId}">${icon('lock')} Locked</button>`:e.source==='meeting'?`<button class="icon-button" data-action="delete-meeting" data-id="${escape(e.id)}" aria-label="Delete meeting ${escape(e.title)}">${icon('trash')}</button>`:''}</div>`).join(''):`<div class="empty-state">${icon('calendar')}<h3>Blank space is also a possibility for the day.</h3><p>Select a favorite itinerary; it will appear here after confirmation.</p><button class="button" data-action="nav" data-view="planner">Go plan afternoon ${icon('arrow')}</button></div>`}</div><div class="data-note">${icon('shield')} Saved in this browser only. Export  .ics  to import into your calendar; no invitations or bookings are sent.</div></section><aside>${assistantCard()}${remindersCard()}</aside></div>`;}
const articles=[{type:'AI Infrastructure',title:'From compute to application, focus on genuine deployment needs',body:'This card demonstrates how you summarize topics of interest: separating company disclosures from model interpretations while preserving original sources and timestamps.',fact:'Example facts section: after connecting to information feeds, present verifiable company disclosures.',analysis:'Example analysis section: compare demand, capital expenditures, and revenue realization.',source:'NVIDIA Investor relations',url:'https://investor.nvidia.com/',color:'sage',icon:'bolt'}, {type:'Semiconductor',title:'Less chasing volatility, more understanding where changes come from',body:'For the same topic retain context, distinguish what has already happened, analytical assumptions, and information still needing confirmation.',fact:'Example facts section: financial reports, performance explanations, and release times will appear here.',analysis:'Example analysis section: examine product structure and profit margin changes to avoid looking at a single number alone.',source:'AMD Investor relations',url:'https://ir.amd.com/',color:'peach',icon:'spark'}, {type:'Tech trends',title:'Turn information into questions, not anxiety',body:'A two‑minute briefing can leave only three questions relevant to you. Here we show content organization, without providing real‑time news or investment conclusions.',fact:'Example facts section: disclosure documents and company announcements are priority materials for verification.',analysis:'Example pending‑verification section: list the questions that need answering for the next disclosure.',source:'SEC EDGAR',url:'https://www.sec.gov/edgar/search/',color:'lavender',icon:'news'}];
function briefPage(){return `<section class="brief-banner"><div><span class="eyebrow">THE DAILY EDIT · 08:00</span><h2>A little insight,<br>A calm beginning.</h2><p>To follow AI  and semiconductors, here is a clear place to start reading.</p></div><div class="brief-stamp">THE<br><em>daily</em><br>EDIT<span>DAYLIGHT / 001</span></div></section><div class="brief-disclaimer">${icon('info')} The following is an example of briefing structure, with no real‑time news or market data linked; links are official information sources, not news sources for the sample text.</div><div class="article-grid">${articles.map((a,i)=>`<article class="card article-card"><div class="article-top"><span class="round-icon ${a.color}">${icon(a.icon)}</span><span>0${i+1} / Example</span></div><span class="article-category">${a.type}</span><h3>${a.title}</h3><p>${a.body}</p><button class="text-button" data-action="article" data-id="${i}">Read more ${icon('arrow')}</button></article>`).join('')}</div><div class="brief-settings card"><div><h3>${icon('clock')} At your preferred time, encounter the briefing</h3><p>Local briefing 08:00 · U.S. pre‑market based on New York trading days. This version only preview rules, no background push.</p></div><button class="button outline" data-action="preview-brief">Preview a briefing ${icon('arrow')}</button></div>`;}
function memoryPage(){return `<div class="memory-layout"><section><div class="memory-summary"><span class="round-icon sage">${icon('memory')}</span><div><h2>Your preferences</h2><p>Saved in the current browser; view, edit, and delete anytime.</p></div><span class="count-tag">${state.memories.length} memories</span></div><div class="memory-list">${state.memories.map(m=>`<div class="card memory-card"><span class="memory-kind">Long‑term preference</span><h3>${escape(m.label)}</h3><p>${escape(m.detail)}</p><div><span>You can change your mind anytime</span><button class="icon-button" data-action="edit-memory" data-id="${escape(m.id)}" aria-label="Edit${escape(m.label)}">${icon('edit')}</button><button class="icon-button" data-action="delete-memory" data-id="${escape(m.id)}" aria-label="Delete${escape(m.label)}">${icon('trash')}</button></div></div>`).join('')}</div><button class="add-memory" data-action="add-memory">${icon('plus')} Add a personal preference</button><div class="card today-context"><h3>Today’s conditions are not permanent for you.</h3><p>Budget ¥${state.constraints.budget}，${time(state.constraints.deadline)}  return deadline. These apply only to this trip and do not automatically become long-term preferences.</p></div><section class="card activity-log">${subtitle('A CLEAR LITTLE TRAIL','What the assistant has done')}<div class="audit-items">${state.audit.length?state.audit.slice(0,8).map(a=>`<div><span>${escape(a.at)}</span><p>${escape(a.text)}</p></div>`).join(''):'<p class="muted">No execution records yet. After confirming the trip or modifying preferences, a record will appear here.</p>'}</div></section></section><aside><section class="privacy-card">${icon('shield')}<h2>Your life,<br>In your control.</h2><p>Queries and suggestions can be completed automatically; decisions about schedule changes always remain with you.</p><div><span>Calendar and memory</span><b>On‑device browser</b></div><div><span>Send invitations / Payments</span><b>Not connected</b></div><div><span>Maps / News data</span><b>Sample data</b></div><div><span>Model service</span><b>${status.mode==='live'?'Nebius Configured':'Local demo parsing'}</b></div><small>${status.mode==='live'?'When submitting travel requests, only toward Nebius Send this request along with budget, time, transportation, and activity constraints; memory lists and calendar content will not be sent.':'The current mode does not send personal data to external models. After configuring the model, the sending scope will be clearly explained.'}</small></section><button class="reset-button" data-action="reset">${icon('undo')} Reset demo data</button></aside></div>`;}
function render(){if(location.hash!=='#'+view)history.pushState(null,'','#'+view);const focused=document.activeElement?.id;$('#app').innerHTML=`<aside class="sidebar"><button class="brand" data-action="nav" data-view="live"><span class="brand-mark">✳</span><span>daylight<span class="brand-dot">.</span></span></button><div class="workspace-label">PERSONAL SPACE</div><nav aria-label="Main navigation">${navs.map(([id,ic,label])=>`<button class="nav-item ${view===id?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='brief'&&!state.briefRead?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-quote"><span>✳</span><p>Less busy.<br>More living.</p><small>Give life a little more breathing space.</small></div><button class="sidebar-status" data-action="about"><span class="status-dot"></span><div>${status.mode==='live'?'Nebius Model configured':'Local demo mode'}<small>${status.mode==='live'?'NVIDIA Nemotron':'All arrangements, confirmed by you'}</small></div>${icon('info')}</button><button class="profile" data-action="nav" data-view="memory"><span class="avatar">Z</span><div><strong>Zhuoer’s space</strong><small>Make room for life.</small></div>${icon('settings')}</button></div></aside><main>${header()}<div class="page-content">${view==='live'?livePage():view==='today'?homePage():view==='planner'?plannerPage():view==='calendar'?calendarPage():view==='brief'?briefPage():memoryPage()}</div><footer class="page-footer"><span>Made for your everyday.</span><span>Daylight · Personal AI Assistant Demo</span></footer></main>`;mountLiveMap();if(focused)document.getElementById(focused)?.focus();}
function confirmPlan(plan=current()){
  if(!plan)return;
  if(!validatePlan(plan,state.constraints,state.meetings,state.locks)){toast('Current conditions have changed; please regenerate the plan.');return;}
  draft=plan;
  const old=state.approved;
  modal(`<span class="modal-symbol">${icon('calendar')}</span><span class="eyebrow">A PLAN, WITH YOUR APPROVAL</span><h2>${old?'This change, confirmed by you':'Just like that, keep a beautiful afternoon.'}</h2><p class="modal-intro">${old?'Below is a comparison of new and old arrangements; before confirmation, the local calendar remains unchanged.':'After confirmation, activities and reminders are saved to the local calendar. No reservations or movie ticket purchases will be sent.'}</p><div class="change-list">${plan.stops.map(s=>{const before=old?.stops.find(x=>x.type===s.type);const locked=state.locks.some(l=>l.id===s.id);return `<div><span class="round-icon ${s.type==='movie'?'lavender':'sage'}">${icon(s.type)}</span><div><strong>${s.name}</strong><small>${before&&(before.start!==s.start||before.id!==s.id)?`<del>${before.name} ${time(before.start)}</del> → `:''}${time(s.start)}–${time(s.end)}</small></div><span class="tag">${locked?'Locked · keep':before&&before.start===s.start&&before.id===s.id?'Unchanged':'Pending confirmation'}</span></div>`;}).join('')}</div><div class="confirm-cost"><span>Estimated total cost <b>¥${plan.cost}</b></span><span>${time(plan.homeAt)} Return home ${icon('check')}</span></div>${!old&&plan.stops.some(s=>s.type==='movie')?'<label class="lock-checkbox"><input id="lock-ticket" type="checkbox" checked> Mark the movie as purchased, preserving showtimes during demo rearrangement <small>Only simulates existing commitments; no actual ticket purchase.</small></label>':''}<div class="modal-actions"><button class="button outline" data-action="close">Think again</button><button class="button" data-action="apply-plan">Confirm${old?'Update':'Arrange'} ${icon('check')}</button></div>`);
}
function applyPlan(){
  if(!draft||!validatePlan(draft,state.constraints,state.meetings,state.locks)){close();toast('Conditions have changed; please preview again.');return;}
  const first=!state.approved;
  if(first&&$('#lock-ticket')?.checked){const film=draft.stops.find(s=>s.type==='movie');if(film)state.locks=[{id:film.id,start:film.start}];}
  state.approved=structuredClone(draft);
  const keep=state.reminders.filter(r=>!r.id.startsWith('plan-'));
  state.reminders=[...keep,...draft.stops.map(s=>({id:'plan-'+s.type,title:s.type==='movie'?'Before the movie starts, remember to depart':TYPES[s.type],detail:`${time(s.start)} · ${s.name} · Calendar reminder list`,done:false}))];
  audit(`${first?'Confirm':'Update'}Local itinerary:${draft.stops.length} item activities, estimated ¥${draft.cost}，${time(draft.homeAt)} Return home; no contact with merchants.`);
  save();calculate();close();assistant=state.locks.length?'The itinerary has been recorded in the local calendar. Movie showtimes are locked; if changes occur later, I will first keep it, then coordinate other arrangements.':'Itinerary and reminders have been recorded in the local calendar. You can also export the calendar file and bring it to your own calendar app.';render();toast(first?'Itinerary and reminders have been saved to the local calendar':'Calendar updated, locked arrangements remain unchanged');
}
function meetingModal(){modal(`<span class="modal-symbol">${icon('calendar')}</span><span class="eyebrow">A CHANGE OF PLANS</span><h2>An extra meeting was added temporarily</h2><p class="modal-intro">Add an online meeting to see how it affects your afternoon. The meeting is only written into the demo calendar, no invitations sent.</p><form id="meeting-form"><label>Meeting name<input name="title" value="Project kickoff meeting" maxlength="60" required></label><div class="form-grid two"><label>Start time<input name="start" type="time" value="14:00" required></label><label>End time<input name="end" type="time" value="15:00" required></label></div><div class="notice">${icon('info')} Online meetings can be joined from the current location; no activities or transport will be scheduled during the meeting.</div><div class="modal-actions"><button type="button" class="button outline" data-action="close">Cancel</button><button type="submit" class="button">Add and check conflicts ${icon('arrow')}</button></div></form>`);}
function repair(){calculate();const p=current();if(!p){modal(`<span class="modal-symbol">${icon('info')}</span><h2>This time, some trade‑offs are needed.</h2><p>${escape(result.reason)}</p><div class="notice">Existing itinerary and locked showtimes remain unchanged. Please resolve the above conflicts first, then preview the new arrangement.</div><div class="modal-actions"><button class="button outline" data-action="close">Keep original plan</button>${result.reasonType==='locked-conflict'?`<button class="button" data-action="nav" data-view="calendar">Go back to calendar to adjust meeting ${icon('arrow')}</button>`:`<button class="button" data-action="edit-constraints">Adjust conditions ${icon('arrow')}</button>`}</div>`);return;}confirmPlan(p);}
function trace(){const p=current();modal(`<span class="modal-symbol">${icon('shield')}</span><span class="eyebrow">GROUNDED IN CONSTRAINTS</span><h2>Every suggestion has been checked.</h2><p class="modal-intro">from ${result.checked} found among candidate permutations ${result.feasible||0} Feasible arrangements, then sorted by different preferences. The three options are differing candidates; no guarantee of global optimum for each objective.</p><div class="trace-list">${[['Data source','Built‑in fictional locations, prices, operating windows, and traffic estimates'],['Budget constraint',p?`¥${p.cost} ≤ ¥${state.constraints.budget}`:'No feasible solution currently'],['Home‑return constraint',p?`${time(p.homeAt)} ≤ ${time(state.constraints.deadline)}`:'No feasible solution currently'],['Calendar conflict',`${state.meetings.length} sessions of online meetings; activities and transport cannot overlap`],['Confirmed commitments',state.locks.length?'Locked movie venue and showtime must be maintained':'No locked activities currently'],['Actual reservations','Not yet integrated with merchants, ticketing, real maps, or external calendars']].map(([a,b])=>`<div>${icon('check')}<div><strong>${a}</strong><p>${b}</p></div></div>`).join('')}</div><button class="button full" data-action="close">Got it</button>`);}
function showStop(id){const stop=current()?.stops.find(s=>s.id===id);if(!stop)return;selectedStop=id;render();modal(`<span class="modal-symbol">${icon(stop.type)}</span><span class="eyebrow">A LITTLE STOP ALONG THE WAY</span><h2>${stop.name}</h2><p>${stop.note}</p><div class="place-facts"><div><small>Scheduled time</small><strong>${time(stop.start)}–${time(stop.end)}</strong></div><div><small>Estimated cost</small><strong>¥${stop.price}</strong></div><div><small>Sample rating</small><strong>★ ${stop.rating}</strong></div></div><div class="notice">This is a fictional demo location. Business hours ${time(stop.open)}–${time(stop.close)}; ratings, showtimes, and prices are not real‑time queries, and reservations are not yet confirmed.</div><button class="button full" data-action="close">Back to my plan</button>`);}
function reminderModal(){modal(`<span class="modal-symbol">${icon('coffee')}</span><span class="eyebrow">A SMALL PAUSE HELPS</span><h2>Take care of yourself and schedule it too.</h2><p class="modal-intro">Try a 10 second activity reminder; only triggers when the page stays open; this demo Does not detect posture, and does not push in background.</p><label class="toggle-row">Meeting / Do Not Disturb mode <input id="dnd" type="checkbox" ${state.dnd?'checked':''}></label><p class="muted">When enabled, this reminder will be delayed until you manually turn off Do Not Disturb before trying again.</p><div class="modal-actions"><button class="button outline" data-action="close">Close</button><button class="button" data-action="start-reminder">10  seconds from now ${icon('bell')}</button></div>`);}
function memoryModal(id){const m=state.memories.find(x=>x.id===id);modal(`<span class="modal-symbol">${icon('memory')}</span><h2>${m?'Edit this preference':'Let me know you better'}</h2><p class="modal-intro">${m?.kind==='budget'?'After saving, used as budget for new plan; confirmed calendar will not update automatically.':m?.kind==='transport'?'After saving, used as transportation choice for new plan.':'Text preferences are stored locally to display personal background; current schedule uses only budget and transport preferences.'}</p><form id="memory-form" data-id="${m?.id||''}">${m?.kind==='budget'?`<label>Budget limit<input name="value" type="number" min="0" max="10000" required value="${m.value}"></label>`:m?.kind==='transport'?`<label>Default travel mode<select name="value"><option value="transit" ${m.value==='transit'?'selected':''}>Public transit priority</option><option value="walk" ${m.value==='walk'?'selected':''}>Walking all the way</option></select></label>`:`<label>Preference content<input name="value" maxlength="80" required placeholder="Example: like a quiet little shop" value="${escape(m?.label||'')}"></label>`}<div class="modal-actions"><button type="button" class="button outline" data-action="close">Cancel</button><button type="submit" class="button">Save preference ${icon('check')}</button></div></form>`);}
function about(){modal(`<span class="modal-symbol">${icon('sun')}</span><h2>Meet Daylight.</h2><p class="modal-intro">A personal assistant that turns your daily intentions into feasible arrangements and re‑coordinates them when things change. demo。</p><div class="notice">Current${status.mode==='live'?'Configured Nebius / NVIDIA Nemotron Intent parsing; model connection subject to actual call results':'Using local preset scenario parsing, no large model invoked'}Scheduling and constraint checks run actually; maps, places, information, and tickets are examples.</div><p>Calendar, preferences, and reminders are stored in the current browser; no real bookings, transactions, invitation sends, or background tasks.</p><button class="button full" data-action="close">Start exploring ${icon('arrow')}</button>`);}
async function submitIntent(text){if(busy)return;intentText=text;busy=true;assistant='Understanding your needs and checking which arrangements work…';render();try{const response=await fetch('/api/intent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,current:state.constraints})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Request failed');assistant=data.message;if(data.supported){state.constraints=data.constraints;calculate();save();audit(`According to${data.mode==='live'?'Nebius model':'local scenario'}Parsing updates candidate conditions; confirmed calendar not yet modified.`);save();}else toast(data.message);}catch(e){assistant=e.message;toast(e.message);}finally{busy=false;render();$('#plan-section')?.scrollIntoView({behavior:'smooth',block:'start'});}}
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action]');if(!el)return;
  const a=el.dataset.action,id=el.dataset.id;
  if(a==='nav'){if($('#modal').open)close();view=el.dataset.view;if(view==='brief'){state.briefRead=true;save();}render();window.scrollTo({top:0,behavior:'smooth'});}
  else if(a==='focus-plan'){view='live';render();document.querySelector('[data-journey-field="text"]')?.focus();}
  else if(a==='close')close();
  else if(a==='sample'){$('#intent').value='Today I want a haircut, eat ramen, watch a movie, budget 200  CNY, using transit, return by  8  pm.';$('#intent').focus();}
  else if(a==='select-plan'){selected=id;selectedStop=null;render();}
  else if(a==='confirm-plan')confirmPlan();
  else if(a==='apply-plan')applyPlan();
  else if(a==='add-meeting')meetingModal();
  else if(a==='repair')repair();
  else if(a==='trace')trace();
  else if(a==='stop')showStop(id);
  else if(a==='edit-constraints'){close();view='planner';render();$('.constraints').open=true;$('.constraints input').focus();$('.constraints').scrollIntoView({behavior:'smooth'});}
  else if(a==='notifications'){modal(`<span class="modal-symbol">${icon('bell')}</span><h2>Record it here, so you don’t have to keep thinking about it.</h2>${state.reminders.map(r=>`<div class="notification-item">${icon(r.done?'check':'clock')}<div><strong>${escape(r.title)}</strong><p>${escape(r.detail)}</p></div></div>`).join('')}<p class="muted">Schedule reminders are a local list; push notifications at time are not yet enabled.</p><button class="button full" data-action="close">Got it</button>`);}
  else if(a==='toggle-reminder'){const r=state.reminders.find(x=>x.id===id);r.done=!r.done;save();render();}
  else if(a==='new-reminder'){modal(`<span class="modal-symbol">${icon('bell')}</span><h2>Add a little reminder</h2><form id="reminder-form"><label>Reminder content<input name="title" required maxlength="80" placeholder="For example: bring headphones when going out"></label><div class="modal-actions"><button type="button" class="button outline" data-action="close">Cancel</button><button class="button" type="submit">Add to list</button></div></form>`);}
  else if(a==='reminder')reminderModal();
  else if(a==='start-reminder'){state.dnd=$('#dnd').checked;save();clearTimeout(reminderTimer);close();render();toast(state.dnd?'Do Not Disturb is on, this reminder will be postponed':'Okay,10  seconds until your movement reminder');reminderTimer=setTimeout(()=>{if(state.dnd){audit('Activity reminder postponed due to Do Not Disturb; user not interrupted.');save();toast('Activity reminder postponed; wait until you end Do Not Disturb to try again.');return;}audit('In‑app activity reminder triggered.');save();modal(`<span class="modal-symbol">${icon('coffee')}</span><span class="eyebrow">TAKE A LITTLE BREATH</span><h2>A small cup of water, a bit of new energy.</h2><p class="modal-intro">Lift your head, relax your shoulders, take a couple of steps. Your plans are all good here.</p><button class="button full" data-action="close">Okay, take a break ${icon('check')}</button>`);},10000);}
  else if(a==='delete-meeting'){state.meetings=state.meetings.filter(m=>m.id!==id);audit('Delete one local meeting; no cancellation invitation sent.');calculate();save();render();toast('Local meeting removed');}
  else if(a==='unlock'){modal(`<h2>Unlock movie showtimes?</h2><p>Only modify the commitment status of the local demonstration; no ticket refund. After unlocking, the new plan can select other timeslots; the original calendar remains until you confirm update.</p><div class="modal-actions"><button class="button outline" data-action="close">Continue keeping</button><button class="button" data-action="apply-unlock" data-id="${id}">Unlock lock</button></div>`);}
  else if(a==='apply-unlock'){state.locks=state.locks.filter(l=>l.id!==id);audit('Manually unlock demonstration movie showtimes; no actual refund.');save();calculate();close();render();}
  else if(a==='export'){const blob=new Blob([makeICS(allEvents())],{type:'text/calendar;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`Daylight-${state.date}.ics`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);audit('Export local .ics File; not directly written to third‑party calendars.');save();toast('Calendar file exported; you can import it into your own calendar app.');}
  else if(a==='article'){const article=articles[+id];modal(`<span class="eyebrow">${article.type} · Content structure demonstration</span><h2>${article.title}</h2><p>${article.body}</p><div class="article-detail"><span class="tag">Fact section</span><p>${article.fact}</p><span class="tag">Analysis / Pending verification section</span><p>${article.analysis}</p></div><p class="muted">Update time: demo placeholder. No real‑time news fetching, market data, or trading advice.</p><a class="button" href="${article.url}" target="_blank" rel="noopener noreferrer">${article.source} ${icon('external')}</a>`);}
  else if(a==='preview-brief'){state.briefRead=true;audit('Manually preview brief structure; no backend send task created.');save();toast('Brief preview updated; this version has not yet enabled backend sending.');render();}
  else if(a==='add-memory'||a==='edit-memory')memoryModal(id);
  else if(a==='delete-memory'){const m=state.memories.find(x=>x.id===id);if(m?.kind==='transport')state.constraints.transport=DEFAULT.transport;if(m?.kind==='budget')state.constraints.budget=DEFAULT.budget;state.memories=state.memories.filter(x=>x.id!==id);audit('Delete a personal preference; budget or transport reverts to default, confirmed calendar unchanged.');save();calculate();render();toast('Preference deleted');}
  else if(a==='about')about();
  else if(a==='reset'){modal(`<h2>Start afresh from a clear afternoon</h2><p>Will clear demo the demo’s local calendar, memories, reminders, and operation records, restoring the initial example. Other apps are unaffected.</p><div class="modal-actions"><button class="button outline" data-action="close">Retain data</button><button class="button" data-action="apply-reset">Reset demo</button></div>`);}
  else if(a==='apply-reset'){clearTimeout(reminderTimer);state=seed();selected='relaxed';assistant='What you want to do, leave it to me to arrange together. Today’s plan will reference your travel preferences and leave buffer for each leg.';save();calculate();close();view='today';render();toast('Initial demo restored');}
});
const minutes=s=>{const [h,m]=s.split(':').map(Number);return h*60+m;};
document.addEventListener('submit',e=>{
  e.preventDefault();const form=e.target,data=new FormData(form);
  try{
    if(form.id==='intent-form'){const text=data.get('intent').trim();if(text)submitIntent(text);else $('#intent').focus();}
    else if(form.id==='constraints-form'){
      const c={budget:+data.get('budget'),start:minutes(data.get('start')),deadline:minutes(data.get('deadline')),transport:data.get('transport'),activities:data.getAll('activities')};
      const next=planDay(c,state.meetings,state.locks);state.constraints=c;result=next;save();assistant=next.plans.length?'Plans re‑compared under new conditions; confirmed calendar stays unchanged until you preview and confirm update.':next.reason;render();toast('Candidate plan updated');
    }else if(form.id==='meeting-form'){
      const start=minutes(data.get('start')),end=minutes(data.get('end'));if(start>=end)throw new Error('Meeting end time must be later than start time.');
      if(state.meetings.some(m=>m.start<end&&start<m.end))throw new Error('This meeting overlaps with an existing meeting; please adjust the time.');
      state.meetings.push({id:crypto.randomUUID(),title:data.get('title').trim(),start,end});audit(`Add local online meeting ${time(start)}–${time(end)}; no invitation sent.`);calculate();save();close();view='calendar';const n=state.approved?conflicts(state.approved,state.meetings).length:0;assistant=n?'The new meeting conflicts with the original schedule. I have re‑checked candidate arrangements; locked movies remain as‑is. Preview the changes before deciding whether to update.':'Meeting recorded in local calendar. Candidate schedule already avoids the meeting period; you can continue to pick preferred arrangements.';render();if(n)repair();else toast('Meeting added; current confirmed schedule has no conflict');
    }else if(form.id==='reminder-form'){const title=data.get('title').trim();if(!title)throw new Error('Please enter reminder content.');state.reminders.unshift({id:crypto.randomUUID(),title,detail:'Personal memo · Local list',done:false});save();close();render();toast('Reminder noted');}
    else if(form.id==='memory-form'){
      const existing=state.memories.find(m=>m.id===form.dataset.id),value=data.get('value').trim();if(!value)throw new Error('Please enter preference content.');
      if(existing?.kind==='budget'){existing.value=+value;existing.label=`Afternoon travel budget ¥${+value}`;state.constraints.budget=+value;}
      else if(existing?.kind==='transport'){existing.value=value;existing.label=value==='transit'?'Prioritize public transport':'Prefer walking all the way';state.constraints.transport=value;}
      else if(existing){existing.label=value;existing.value=value;existing.kind='note';existing.detail='Personal note · Not currently participating in schedule filtering';}
      else state.memories.push({id:crypto.randomUUID(),label:value,value,kind:'note',detail:'Personal note · Not currently participating in schedule filtering'});
      audit('Save personal preference locally; confirmed calendar unchanged.');calculate();save();close();render();toast('Remembered, you can modify anytime');
    }
  }catch(error){toast(error.message);}
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-action]')){e.preventDefault();showStop(e.target.dataset.id);}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&document.activeElement?.id==='intent')$('#intent-form').requestSubmit();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)close();}});
document.addEventListener('input',e=>{if(e.target.id==='intent')intentText=e.target.value;});
window.addEventListener('hashchange',()=>{view=viewFromHash();render();});
render();
fetch('/api/status').then(r=>{if(!r.ok)throw new Error();return r.json();}).then(s=>{status=s;render();}).catch(()=>{assistant='Unable to connect to local service. Please open using the launch script. demo。';render();});





